mapper.select:
select d.id, d.stall_id, d.category_id, d.name, d.price, d.ingredients, d.image, d.description,
       d.status, d.audit_status, d.audit_remark, d.sales, d.stock, d.daily_limit, d.create_time, d.update_time,
       s.name stallName, s.merchant_id, c.name categoryName,
       n.calorie, n.protein, n.fat, n.carbohydrate,
       (case when n.id is null then 0 else 1 end) nutritionFlag
from dish d
    left join stall s on d.stall_id = s.id
    left join dish_category c on d.category_id = c.id
    left join nutrition n on n.dish_id = d.id


        d.name like CONCAT('%', #{name}, '%')


        and d.stall_id = #{stallId}


        and d.category_id = #{categoryId}


        and d.status = #{status}


        and d.audit_status = #{auditStatus}


        and s.merchant_id = #{merchantId}


order by d.update_time desc, d.id desc

select d.id dishId, d.name dishName, d.price, d.image, d.ingredients, d.stall_id stallId, s.name stallName, d.category_id categoryId, c.name categoryName, n.calorie, n.protein, n.fat, n.carbohydrate, n.fiber, n.sodium, (select round(avg(r.rating), 1) from review r where r.dish_id = d.id and r.status = 1) avgRating from dish d inner join nutrition n on n.dish_id = d.id inner join stall s on d.stall_id = s.id left join dish_category c on d.category_id = c.id where d.status = 1 and d.audit_status = 1 and s.status = 1
and d.category_id = #{categoryId}
and n.calorie <= #{maxCalories}
and s.merchant_id = #{merchantId}
order by d.sales desc, d.id asc
limit #{limitSize}
